-- Permission vocabulary and system roles of the expenses module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the expenses permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('expense:create'::text, 'expense'::text, 'create'::text, 'Create expense'::text),
            ('expense:delete'::text, 'expense'::text, 'delete'::text, 'Delete expense'::text),
            ('expense:purge'::text, 'expense'::text, 'purge'::text, 'Purge expense'::text),
            ('expense:read'::text, 'expense'::text, 'read'::text, 'Read expense'::text),
            ('expense:restore'::text, 'expense'::text, 'restore'::text, 'Restore expense'::text),
            ('expense:update'::text, 'expense'::text, 'update'::text, 'Update expense'::text),
            ('expense_category:create'::text, 'expense_category'::text, 'create'::text, 'Create expense category'::text),
            ('expense_category:delete'::text, 'expense_category'::text, 'delete'::text, 'Delete expense category'::text),
            ('expense_category:purge'::text, 'expense_category'::text, 'purge'::text, 'Purge expense category'::text),
            ('expense_category:read'::text, 'expense_category'::text, 'read'::text, 'Read expense category'::text),
            ('expense_category:restore'::text, 'expense_category'::text, 'restore'::text, 'Restore expense category'::text),
            ('expense_category:update'::text, 'expense_category'::text, 'update'::text, 'Update expense category'::text),
            ('expense_tax_line:create'::text, 'expense_tax_line'::text, 'create'::text, 'Create expense tax line'::text),
            ('expense_tax_line:delete'::text, 'expense_tax_line'::text, 'delete'::text, 'Delete expense tax line'::text),
            ('expense_tax_line:purge'::text, 'expense_tax_line'::text, 'purge'::text, 'Purge expense tax line'::text),
            ('expense_tax_line:read'::text, 'expense_tax_line'::text, 'read'::text, 'Read expense tax line'::text),
            ('expense_tax_line:restore'::text, 'expense_tax_line'::text, 'restore'::text, 'Restore expense tax line'::text),
            ('expense_tax_line:update'::text, 'expense_tax_line'::text, 'update'::text, 'Update expense tax line'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('expense:create'::text, 'expense'::text, 'create'::text, 'Create expense'::text),
            ('expense:delete'::text, 'expense'::text, 'delete'::text, 'Delete expense'::text),
            ('expense:purge'::text, 'expense'::text, 'purge'::text, 'Purge expense'::text),
            ('expense:read'::text, 'expense'::text, 'read'::text, 'Read expense'::text),
            ('expense:restore'::text, 'expense'::text, 'restore'::text, 'Restore expense'::text),
            ('expense:update'::text, 'expense'::text, 'update'::text, 'Update expense'::text),
            ('expense_category:create'::text, 'expense_category'::text, 'create'::text, 'Create expense category'::text),
            ('expense_category:delete'::text, 'expense_category'::text, 'delete'::text, 'Delete expense category'::text),
            ('expense_category:purge'::text, 'expense_category'::text, 'purge'::text, 'Purge expense category'::text),
            ('expense_category:read'::text, 'expense_category'::text, 'read'::text, 'Read expense category'::text),
            ('expense_category:restore'::text, 'expense_category'::text, 'restore'::text, 'Restore expense category'::text),
            ('expense_category:update'::text, 'expense_category'::text, 'update'::text, 'Update expense category'::text),
            ('expense_tax_line:create'::text, 'expense_tax_line'::text, 'create'::text, 'Create expense tax line'::text),
            ('expense_tax_line:delete'::text, 'expense_tax_line'::text, 'delete'::text, 'Delete expense tax line'::text),
            ('expense_tax_line:purge'::text, 'expense_tax_line'::text, 'purge'::text, 'Purge expense tax line'::text),
            ('expense_tax_line:read'::text, 'expense_tax_line'::text, 'read'::text, 'Read expense tax line'::text),
            ('expense_tax_line:restore'::text, 'expense_tax_line'::text, 'restore'::text, 'Restore expense tax line'::text),
            ('expense_tax_line:update'::text, 'expense_tax_line'::text, 'update'::text, 'Update expense tax line'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
